@@ -0,0 +1,16 @@
+//! Build script.
+//!
+//! It only exists to declare the custom `docsrs` cfg. Declaring it with
+//! `rustc-check-cfg` keeps `unexpected_cfgs` warnings quiet, and gating it on
+//! the `DOCS_RS` environment variable is the standard way to enable
+//! nightly-only `doc(cfg(...))` annotations when the crate is built on
+//! docs.rs.
+
+fn main() {
+    println!("cargo::rerun-if-changed=build.rs");
+    println!("cargo::rustc-check-cfg=cfg(docsrs)");
+
+    if std::env::var_os("DOCS_RS").is_some() {
+        println!("cargo::rustc-cfg=docsrs");
+    }
+}

Index: src/lib.rs
===================================================================
--- src/lib.rs	
+++ src/lib.rs	
@@ -0,0 +1,73 @@
+#![cfg_attr(not(feature = "std"), no_std)]
+#![cfg_attr(docsrs, feature(doc_cfg))]
+#![warn(missing_docs)]
+
+//! # `xplat`
+//!
+//! A tiny library that shows how to keep conditional compilation clean and
+//! readable when code has to serve many target platforms.
+//!
+//! ## The pattern
+//!
+//! All target detection is concentrated in the [`platform`] module. Callers
+//! depend on a single, target-independent API instead of sprinkling `#[cfg]`
+//! attributes throughout the crate:
+//!
+//! ```
+//! let platform = xplat::Platform::current();
+//! println!("running on {platform}");
+//! ```
+//!
+//! Three mechanisms work together:
+//!
+//! * [`cfg_if!`](https://docs.rs/cfg-if) for readable `if` / `else if` chains
+//!   instead of stacking mutually exclusive `#[cfg]` attributes on every item.
+//! * `[target.'cfg(...)'.dependencies]` in `Cargo.toml` so OS-specific crates
+//!   such as `libc` are only compiled for the OS that needs them.
+//! * A `std` feature for capability gating that is orthogonal to the target.
+
+pub mod platform;
+
+pub use platform::{EXE_SUFFIX, NEWLINE, PATH_SEPARATOR, Platform, process_id};
+
+/// Returns the path of the currently running executable.
+///
+/// This is only available when the `std` feature is enabled, because it relies
+/// on [`std::env`].
+#[cfg(feature = "std")]
+#[cfg_attr(docsrs, doc(cfg(feature = "std")))]
+pub fn current_exe() -> std::io::Result<std::path::PathBuf> {
+    std::env::current_exe()
+}
+
+#[cfg(test)]
+mod tests {
+    use super::*;
+
+    #[test]
+    fn reports_a_platform_name() {
+        assert!(!Platform::current().name().is_empty());
+    }
+
+    #[test]
+    fn newline_matches_the_platform() {
+        if cfg!(windows) {
+            assert_eq!(NEWLINE, "\r\n");
+        } else {
+            assert_eq!(NEWLINE, "\n");
+        }
+    }
+
+    #[test]
+    fn process_id_is_nonzero_on_native_targets() {
+        if !cfg!(target_arch = "wasm32") {
+            assert_ne!(process_id(), 0);
+        }
+    }
+
+    #[cfg(feature = "std")]
+    #[test]
+    fn current_exe_resolves() {
+        assert!(current_exe().is_ok());
+    }
+}

Index: src/platform/mod.rs
===================================================================
--- src/platform/mod.rs	
+++ src/platform/mod.rs	
@@ -0,0 +1,95 @@
+//! Target detection and OS-specific primitives.
+//!
+//! Every `#[cfg]` decision lives behind this module so the rest of the crate
+//! can stay target-agnostic. The dispatch below uses [`cfg_if!`] instead of a
+//! stack of mutually exclusive `#[cfg]` attributes, which keeps the mapping
+//! from target to implementation readable in one place.
+//!
+//! [`cfg_if!`]: https://docs.rs/cfg-if
+
+use core::fmt;
+
+cfg_if::cfg_if! {
+    if #[cfg(target_arch = "wasm32")] {
+        mod wasm;
+        pub use wasm::{EXE_SUFFIX, NEWLINE, PATH_SEPARATOR, process_id};
+    } else if #[cfg(unix)] {
+        mod unix;
+        pub use unix::{EXE_SUFFIX, NEWLINE, PATH_SEPARATOR, process_id};
+    } else if #[cfg(windows)] {
+        mod windows;
+        pub use windows::{EXE_SUFFIX, NEWLINE, PATH_SEPARATOR, process_id};
+    } else {
+        mod unsupported;
+        pub use unsupported::{EXE_SUFFIX, NEWLINE, PATH_SEPARATOR, process_id};
+    }
+}
+
+/// The operating-system family this crate was compiled for.
+#[derive(Clone, Copy, Debug, Eq, Hash, PartialEq)]
+#[non_exhaustive]
+pub enum Platform {
+    /// Linux.
+    Linux,
+    /// macOS.
+    MacOs,
+    /// Windows.
+    Windows,
+    /// FreeBSD.
+    FreeBsd,
+    /// Android.
+    Android,
+    /// iOS.
+    Ios,
+    /// WebAssembly (`target_arch = "wasm32"`).
+    Wasm,
+    /// Any other target, carrying its `target_os` value.
+    Other(&'static str),
+}
+
+impl Platform {
+    /// Returns the [`Platform`] for the current compilation target.
+    #[must_use]
+    pub const fn current() -> Self {
+        cfg_if::cfg_if! {
+            if #[cfg(target_arch = "wasm32")] {
+                Self::Wasm
+            } else if #[cfg(target_os = "linux")] {
+                Self::Linux
+            } else if #[cfg(target_os = "macos")] {
+                Self::MacOs
+            } else if #[cfg(windows)] {
+                Self::Windows
+            } else if #[cfg(target_os = "freebsd")] {
+                Self::FreeBsd
+            } else if #[cfg(target_os = "android")] {
+                Self::Android
+            } else if #[cfg(target_os = "ios")] {
+                Self::Ios
+            } else {
+                Self::Other(core::env::consts::OS)
+            }
+        }
+    }
+
+    /// Returns a lowercase, machine-friendly name such as `"linux"`.
+    #[must_use]
+    pub const fn name(self) -> &'static str {
+        match self {
+            Self::Linux => "linux",
+            Self::MacOs => "macos",
+            Self::Windows => "windows",
+            Self::FreeBsd => "freebsd",
+            Self::Android => "android",
+            Self::Ios => "ios",
+            Self::Wasm => "wasm",
+            Self::Other(name) => name,
+        }
+    }
+}
+
+impl fmt::Display for Platform {
+    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
+        f.write_str(self.name())
+    }
+}

